// ✅ Pull binary files directly from the file nodes
const intraBinary = $('Intra role to File4').first().binary || {};
const interBinary = $('Inter role data to File5').first().binary || {};

// ✅ Count rows inside Excel binary (excluding header and placeholder rows)
function countExcelRows(binary, fieldName) {
  try {
    const b64 = binary[fieldName]?.data;
    if (!b64) return 0;
    const buf = Buffer.from(b64, 'base64');
    const workbook = require('xlsx').read(buf, { type: 'buffer' });
    const sheet = workbook.Sheets[workbook.SheetNames[0]];
    const rows = require('xlsx').utils.sheet_to_json(sheet);
    return rows.filter(r => {
      const values = Object.values(r).map(v => String(v || '').trim());
      // Skip rows where ALL fields are empty
      if (values.every(v => v === '')) return false;
      // Skip placeholder rows like "No Inter-Role..." or "No Intra-Role..."
      if (values.some(v => v.startsWith('No '))) return false;
      // ✅ FIXED: was r["User"], now r["User Name"] to match updated headers
      if (!r["User Name"] || String(r["User Name"]).trim() === '') return false;
      return true;
    }).length;
  } catch (e) {
    return 0;
  }
}

const intraCount = countExcelRows(intraBinary, 'Intra role conflict');
const interCount = countExcelRows(interBinary, 'Inter role conflict');
const totalCount = intraCount + interCount;

// ✅ Extract recipient email
const email = $json["Send to"] || $json["to"] || "team@company.com";
let firstName = "Team";
if (email && typeof email === "string") {
  const raw = email.split("@")[0].split(/[._-]/).find(Boolean);
  if (raw) {
    firstName = raw.charAt(0).toUpperCase() + raw.slice(1).toLowerCase();
  }
}

// ✅ Build HTML email body
const htmlBody = `
<p>Hello ${firstName},</p>
<p>Please find attached the latest <b>SoD Violation Reports</b>:</p>
<ul>
  <li>Intra-Role Conflicts</li>
  <li>Inter-Role Conflicts</li>
</ul>
<p><b>Summary:</b></p>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse; font-family:Arial, sans-serif; font-size:14px;">
  <tr style="background-color:#f2f2f2;">
    <th align="left">Conflict Type</th>
    <th align="right">Count</th>
  </tr>
  <tr><td>Intra-Role Conflicts</td><td align="right">${intraCount}</td></tr>
  <tr><td>Inter-Role Conflicts</td><td align="right">${interCount}</td></tr>
  <tr><td><b>Total Violations</b></td><td align="right"><b>${totalCount}</b></td></tr>
</table>
<p>Regards,<br><b>IT Internal Audit Team</b></p>
`;

// ✅ Merge both binaries for email attachments
const mergedBinary = {
  ...intraBinary,
  ...interBinary
};

return [
  {
    json: {
      to: email,
      subject: totalCount === 0
        ? `SoD Report – No Conflicts Found`
        : `SoD Alert – ${totalCount} Violations Detected`,
      htmlBody,
      intraCount,
      interCount,
      totalCount,
    },
    binary: mergedBinary
  }
];
